-- Step 1: Create Master Key if it does not exist
IF NOT EXISTS (SELECT * FROM sys.symmetric_keys WHERE name = '##MS_DatabaseMasterKey##')
BEGIN
    CREATE MASTER KEY ENCRYPTION BY PASSWORD = 'rafiul735150@#';
END;

-- Step 2: Create Database Scoped Credential if it does not exist
IF NOT EXISTS (SELECT * FROM sys.database_scoped_credentials WHERE name = 'advwrk')
BEGIN
    CREATE DATABASE SCOPED CREDENTIAL advwrk
    WITH IDENTITY = 'Managed Identity';
END;

-- Step 3: Create External Data Source if it does not exist
IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'SilverData')
BEGIN
    CREATE EXTERNAL DATA SOURCE SilverData
    WITH (
        LOCATION = 'https://advwprojectstorage.blob.core.windows.net/silver',
        CREDENTIAL = advwrk
    );
END;

